  function stageModal(stage={}){const html=`<div class="modal-backdrop"><div class="modal compact"><div class="modal-head"><div><h3>${stage.id?'Editar coluna':'Nova coluna'}</h3><div class="help">Defina o nome e o comportamento da etapa.</div></div><button class="close" data-close>×</button></div><form id="stage-form"><div class="field"><label>Nome da coluna<input class="input" name="name" required maxlength="80" value="${esc(stage.name||'')}"></label></div><div class="form-grid"><div class="field"><label>Tipo da etapa<select class="select" name="kind">${[['inbox','Entrada'],['analysis','Análise'],['waiting','Aguardando'],['planned','Planejado'],['production','Produção'],['approval','Aprovação'],['completed','Concluído'],['cancelled','Cancelado'],['archived','Arquivado']].map(x=>`<option value="${x[0]}" ${(stage.kind||'production')===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label></div><div class="field"><label>Marcador<input class="input" name="color" type="color" value="${esc(stage.color||'#737373')}"></label></div></div><div class="form-actions"><button type="button" class="ghost" data-close>Cancelar</button><button class="primary">Salvar coluna</button></div></form></div></div>`;$('#modal-root').innerHTML=html;$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#stage-form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.id=stage.id||0;try{await api('stages.save',p,'POST');S.meta=await api('meta');toast('Coluna salva');closeModal();renderKanban()}catch(x){toast(x.message,true)}}}
  function stageDeleteModal(id,rows,stages){const stage=stages.find(s=>s.id==id),count=rows.filter(r=>r.stage_id==id).length,others=stages.filter(s=>s.id!=id);const html=`<div class="modal-backdrop"><div class="modal compact"><div class="modal-head"><div><h3>Excluir “${esc(stage?.name||'coluna')}”?</h3><div class="help">A coluna será removida do Kanban.</div></div><button class="close" data-close>×</button></div><div class="danger-box">${count?`Existem <b>${count}</b> task(s) nesta coluna. Escolha para onde elas devem ir antes de excluir.`:'Esta coluna está vazia. A exclusão não poderá ser desfeita.'}</div>${count?`<div class="field"><label>Mover tasks para<select class="select" id="delete-stage-target">${others.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label></div>`:''}<div class="form-actions"><button class="ghost" data-close>Cancelar</button><button class="danger" id="confirm-stage-delete">Excluir coluna</button></div></div></div>`;$('#modal-root').innerHTML=html;$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#confirm-stage-delete').onclick=async()=>{try{await api('stages.delete',{id,move_to_stage_id:count?Number($('#delete-stage-target').value):0},'POST');S.meta=await api('meta');toast('Coluna excluída');closeModal();renderKanban()}catch(x){toast(x.message,true)}}}
  async function renderDemandList(){
    const rows=await loadDemands({include_closed:1});
    $('#content').innerHTML=`<div class="section-title"><div><h3>Tasks</h3><div class="panel-sub">Acompanhe entregas, responsáveis e andamento em uma visão objetiva.</div></div><button class="primary" id="list-new">+ Nova task</button></div><div class="panel clean-panel"><div class="toolbar"><div class="search-box"><span>⌕</span><input class="input" id="list-q" placeholder="Buscar task ou cliente"></div><select class="select" id="list-stage"><option value="">Todas as etapas</option>${S.meta.stages.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="table-wrap"><table class="table"><thead><tr><th>Task</th><th>Cliente</th><th>Etapa</th><th>Entrega</th><th>Responsável</th><th>Comercial</th></tr></thead><tbody id="demand-table"></tbody></table></div></div>`;
    function paint(){const q=($('#list-q').value||'').toLowerCase(),st=$('#list-stage').value;$('#demand-table').innerHTML=rows.filter(d=>(!q||(`${d.title} ${d.client_name}`).toLowerCase().includes(q))&&(!st||d.stage_id==st)).map(d=>`<tr data-demand="${d.id}"><td><div class="row-title"><b>${esc(d.title)}</b><span>#${d.id} · ${esc(d.category_name)}</span></div></td><td>${esc(d.client_name)}</td><td><span class="badge"><i class="dot" style="background:${esc(d.stage_color)}"></i>${esc(d.stage_name)}</span></td><td class="${d.due_at&&new Date(d.due_at.replace(' ','T')+'Z')<new Date()?'red':''}">${time(d.due_at)}</td><td>${esc(d.assigned_name||'Sem responsável')}</td><td>${d.billing_mode==='included'?'<span class="tag">Incluso no mensal</span>':d.amount_cents!==undefined?money(d.amount_cents||0):'—'}</td></tr>`).join('')||`<tr><td colspan="6"><div class="empty">Nenhuma task encontrada.</div></td></tr>`;$$('#demand-table tr[data-demand]').forEach(x=>x.onclick=()=>openDemand(Number(x.dataset.demand)))}
    paint();$('#list-q').oninput=paint;$('#list-stage').onchange=paint;$('#list-new').onclick=()=>openDemand();
  }
  async function openDemand(id=0,edit=false,initialStage=0){
    let d=null;if(id){try{d=await api('demands.get',{id})}catch(e){toast(e.message,true);return}}
    if(d&&!edit){const html=`<div class="modal-backdrop task-backdrop"><button class="task-screen-close" data-close aria-label="Fechar task" title="Fechar">×</button><div class="modal wide task-detail-modal"><div class="modal-head"><div><span class="eyebrow">TASK #${d.id}</span><h3>${esc(d.title)}</h3><div class="help">Detalhes, arquivos, aprovações e histórico do job.</div></div></div>${detailHtml(d)}</div></div>`;$('#modal-root').innerHTML=html;$$('[data-close]').forEach(x=>x.onclick=closeModal);const backdrop=$('#modal-root .task-backdrop');if(backdrop)backdrop.onclick=e=>{if(e.target===backdrop)closeModal()};wireDetail(d);return}
    const admin=S.user.role==='admin',client=S.user.role==='client';const fallbackClient=client&&S.meta.clients.length===1?S.meta.clients[0].id:'';const clientId=d?.client_id||fallbackClient||S.meta.clients[0]?.id||'';const cat=d?.category_id||S.meta.categories[0]?.id||'';
    const html=`<div class="modal-backdrop task-backdrop"><button class="task-screen-close" data-close aria-label="Fechar task" title="Fechar">×</button><div class="modal wide task-modal"><div class="modal-head"><div><span class="eyebrow">${d?'EDIÇÃO':'NOVA TASK'}</span><h3>${d?'Editar task #'+d.id:client?'Nova solicitação':'Nova task'}</h3><div class="help">Briefing enxuto, prazo de entrega e arquivos no Drive em um único fluxo.</div></div></div>${demandFormHtml(d,client,clientId,cat)}</div></div>`;
    $('#modal-root').innerHTML=html;$$('[data-close]').forEach(x=>x.onclick=closeModal);const taskBackdrop=$('#modal-root .task-backdrop');if(taskBackdrop)taskBackdrop.onclick=e=>{if(e.target===taskBackdrop)closeModal()};wireMarkdownEditor();
    const form=$('#demand-form'),clientSelect=$('#demand-client'),billing=$('#billing-mode'),amountWrap=$('#amount-field'),billingWrap=$('#billing-field'),commercialHint=$('#commercial-hint');
    moneyInput($('#amount-brl'),d?.amount_cents||0);
    const syncCommercial=()=>{if(!admin)return;const cid=Number(clientSelect?.value||clientId),c=S.meta.clients.find(x=>Number(x.id)===cid),monthly=c?.commercial_type==='monthly';if(billingWrap)billingWrap.classList.toggle('hidden',!monthly);if(billing){if(!monthly)billing.value='one_off';else if(!['included','one_off'].includes(billing.value))billing.value='included'}const included=monthly&&billing?.value==='included';amountWrap?.classList.toggle('hidden',included);if(commercialHint)commercialHint.innerHTML=monthly?`Cliente mensal · ${money(c?.monthly_amount_cents||0)}/mês${included?' · esta task será incluída no pacote':''}`:'Cliente avulso · informe o valor deste serviço';};
    const fileInput=$('#demand-files'),fileList=$('#selected-files'),driveHelp=$('#demand-drive-help'),driveDrop=$('#demand-upload-drop'),pendingFiles=[];
    const syncDrive=()=>{const cid=Number(clientSelect?.value||clientId),c=clientDriveInfo(cid),ready=!!c?.drive_ready;if(fileInput)fileInput.disabled=!ready;if(driveDrop)driveDrop.classList.toggle('disabled',!ready);if(driveHelp)driveHelp.textContent=ready?`Arquivos deste cliente serão enviados para ${c?.drive_email||'o Google Drive configurado'}.`:'Este cliente ainda não possui um Google Drive disponível. Defina no cadastro do cliente ou configure o Drive padrão.';};
    clientSelect?.addEventListener('change',()=>{if(admin&&billing){const c=S.meta.clients.find(x=>Number(x.id)===Number(clientSelect.value));billing.value=c?.commercial_type==='monthly'?'included':'one_off'}syncCommercial();syncDrive()});billing?.addEventListener('change',syncCommercial);syncCommercial();syncDrive();
    const renderPendingFiles=()=>{if(!fileList)return;fileList.innerHTML=pendingFiles.length?pendingFiles.map((f,i)=>`<span>${esc(f.name)} <small>${Math.max(1,Math.round(f.size/1024))} KB</small><button type="button" class="selected-file-remove" data-remove-file="${i}" aria-label="Remover ${esc(f.name)}">×</button></span>`).join(''):'<span class="muted">Nenhum arquivo selecionado.</span>';$$('[data-remove-file]').forEach(b=>b.onclick=()=>{pendingFiles.splice(Number(b.dataset.removeFile),1);renderPendingFiles()})};
    if(fileInput)fileInput.onchange=()=>{for(const f of [...fileInput.files]){const key=`${f.name}:${f.size}:${f.lastModified}`;if(!pendingFiles.some(x=>`${x.name}:${x.size}:${x.lastModified}`===key))pendingFiles.push(f)}fileInput.value='';renderPendingFiles()};
    form.onsubmit=async e=>{e.preventDefault();const btn=e.submitter,originalText=btn?.textContent||'';if(btn){btn.disabled=true;btn.textContent='Salvando task…'}const fd=new FormData(form),files=[...pendingFiles],p=Object.fromEntries(fd);delete p.attachments;p.id=d?.id||0;p.version=d?.version||1;p.client_id=d?.client_id||Number(p.client_id||clientId);p.draft=0;if(p.assigned_to)p.assigned_to=Number(p.assigned_to);else delete p.assigned_to;if($('#amount-brl'))p.amount_cents=currencyCents($('#amount-brl'));let saved=null;try{saved=await api('demands.save',p,'POST')}catch(x){toast(x.message,true);if(btn){btn.disabled=false;btn.textContent=originalText}return}if(files.length){try{for(let i=0;i<files.length;i++){await uploadDemandFile(saved.id,files[i],{},pct=>{if(btn)btn.textContent=`Arquivo ${i+1}/${files.length} · ${Math.round(pct*100)}%`})}}catch(x){toast(`Task #${saved.id} foi salva, mas um arquivo não terminou: ${x.message}`,true);closeModal();S.meta=await api('meta');await go('kanban',S.page!=='kanban');return}}toast((d?'Task atualizada #':'Task criada #')+saved.id+(files.length?' · arquivos enviados ao Drive':''));closeModal();S.meta=await api('meta');if(d)await refresh();else await go('kanban',S.page!=='kanban')};
  }
  function demandFormHtml(d,client,clientId,cat){
    const admin=S.user.role==='admin',users=(S.meta.users||[]).filter(u=>u.active!==0&&u.role!=='client'),selectedUser=d?.assigned_to||'',selectedClient=S.meta.clients.find(c=>Number(c.id)===Number(clientId)),monthly=selectedClient?.commercial_type==='monthly',mode=d?.billing_mode||(monthly?'included':'one_off'),firstStage=S.meta.stages[0]?.name||'primeira etapa',delivery=d?.due_at?dateTimeInput(d.due_at):(S.meta.min_delivery_at||''),driveReady=!!selectedClient?.drive_ready;
    return `<form id="demand-form" class="task-form"><div class="task-form-section"><div class="form-section-title"><span>01</span><div><b>Informações principais</b><small>A task nova sempre entra em <strong>${esc(firstStage)}</strong>.</small></div></div><div class="form-grid"><div class="field"><label>Título <em>*</em></label><input class="input" name="title" required maxlength="190" value="${esc(d?.title||'')}" placeholder="Ex.: Reel campanha de lançamento"></div><div class="field"><label>Categoria <em>*</em></label><select class="select" name="category_id" id="demand-cat">${S.meta.categories.map(c=>`<option value="${c.id}" ${c.id==cat?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field ${client&&S.meta.clients.length===1?'hidden':''}"><label>Cliente <em>*</em></label><select class="select" name="client_id" id="demand-client" ${d?'disabled':''}>${S.meta.clients.map(c=>`<option value="${c.id}" ${c.id==clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Data de entrega <em>*</em></label><input class="input" name="due_at" type="datetime-local" required value="${esc(delivery)}" ${d?'':`min="${esc(S.meta.min_delivery_at||'')}"`}><small class="field-help">Prazo mínimo: ${Number(S.meta.min_delivery_business_hours||24)} horas úteis. Ajustável em Configurações.</small></div>${admin?`<div class="field"><label>Responsável</label><select class="select" name="assigned_to"><option value="">Sem responsável</option>${users.map(u=>`<option value="${u.id}" ${u.id==selectedUser?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Prioridade</label><select class="select" name="priority"><option value="low" ${d?.priority==='low'?'selected':''}>Baixa</option><option value="normal" ${!d||d?.priority==='normal'?'selected':''}>Normal</option><option value="high" ${d?.priority==='high'?'selected':''}>Alta</option><option value="urgent" ${d?.priority==='urgent'?'selected':''}>Urgente</option></select></div></div></div>${admin?`<div class="task-form-section"><div class="form-section-title"><span>02</span><div><b>Comercial</b><small id="commercial-hint"></small></div></div><div class="form-grid"><div class="field ${monthly?'':'hidden'}" id="billing-field"><label>Modelo comercial</label><select class="select" name="billing_mode" id="billing-mode"><option value="included" ${mode==='included'?'selected':''}>Incluso no pacote mensal</option><option value="one_off" ${mode==='one_off'?'selected':''}>Serviço avulso</option></select></div><div class="field ${mode==='included'?'hidden':''}" id="amount-field"><label>Valor do serviço</label><input class="input currency-input" id="amount-brl" name="amount_display" inputmode="decimal" autocomplete="off" value="${money(d?.amount_cents||0)}"></div></div></div>`:''}<div class="task-form-section"><div class="form-section-title"><span>${admin?'03':'02'}</span><div><b>Briefing</b><small>Markdown habilitado para organizar títulos, listas, destaques e links.</small></div></div><div class="markdown-editor"><div class="markdown-toolbar"><button type="button" data-md="bold"><b>B</b></button><button type="button" data-md="italic"><i>I</i></button><button type="button" data-md="heading">H2</button><button type="button" data-md="list">• Lista</button><button type="button" data-md="code">&lt;/&gt;</button><button type="button" data-md="link">Link</button><button type="button" class="preview-toggle" id="toggle-brief-preview">Pré-visualizar</button></div><textarea class="textarea briefing-textarea" id="brief-editor" name="brief" required maxlength="20000" placeholder="Descreva objetivo, contexto, referências, textos e observações…">${esc(d?.brief||'')}</textarea><div id="brief-preview" class="markdown-body markdown-preview hidden"></div></div></div><div class="task-form-section"><div class="form-section-title"><span>${admin?'04':'03'}</span><div><b>Arquivos e referências</b><small id="demand-drive-help">${driveReady?`Arquivos deste cliente serão enviados para ${esc(selectedClient?.drive_email||'o Google Drive configurado')}.`:'Este cliente ainda não possui um Google Drive disponível. Defina no cadastro do cliente ou configure o Drive padrão.'}</small></div></div><label id="demand-upload-drop" class="upload-drop ${driveReady?'':'disabled'}"><input id="demand-files" name="attachments" type="file" multiple ${driveReady?'':'disabled'}><span class="upload-icon">↥</span><b>Selecionar arquivos</b><small>Upload em blocos para arquivos grandes. O TaskEsc não impõe limite total quando a configuração estiver em 0; vale o limite disponível na sua conta Google Drive.</small></label><div class="selected-files" id="selected-files"><span class="muted">Nenhum arquivo selecionado.</span></div></div><div class="form-actions sticky-actions"><button type="button" class="ghost" data-close>Cancelar</button><button class="primary">${d?'Salvar alterações':client?'Enviar solicitação':'Salvar task'}</button></div></form>`;
  }
  function detailHtml(d){
    const admin=S.user.role==='admin',client=S.user.role==='client',preview=!!S.user.is_preview,canEdit=!preview&&(admin||client),commercial=d.billing_mode==='included'?'<span class="tag">Incluso no pacote mensal</span>':d.amount_cents!==undefined?`<strong>${money(d.amount_cents||0)}</strong>`:'—',allFiles=d.files||[],finalFiles=allFiles.filter(f=>f.kind==='final'),jobFiles=allFiles.filter(f=>f.kind!=='final');
    return `<div class="task-summary"><div><span>Cliente</span><b>${esc(d.client_name)}</b></div><div><span>Categoria</span><b>${esc(d.category_name)}</b></div><div><span>Etapa</span><b><i class="dot" style="background:${esc(d.stage_color||'#777')}"></i>${esc(d.stage_name)}</b></div><div><span>Entrega</span><b class="${d.due_at&&new Date(d.due_at.replace(' ','T')+'Z')<new Date()?'red':''}">${time(d.due_at)}</b></div><div><span>Responsável</span><b>${esc(d.assigned_name||'Sem responsável')}</b></div><div><span>Prioridade</span><b>${esc(priorityLabel(d.priority))}</b></div>${d.amount_cents!==undefined?`<div><span>Comercial</span><b>${commercial}</b></div>`:''}</div><section class="detail-section"><div class="panel-head"><div><h3>Briefing</h3><div class="panel-sub">Conteúdo formatado em Markdown.</div></div></div><div class="markdown-body">${renderMarkdown(d.brief)}</div></section><section class="detail-section final-delivery-section"><div class="panel-head final-delivery-head"><div><span class="eyebrow">ENTREGA</span><h3>Entrega final</h3><div class="panel-sub">Arquivos marcados como entrega final ficam separados dos materiais de produção.</div></div></div>${finalFiles.length?`<div class="file-grid final-file-grid">${finalFiles.map(fileCardHtml).join('')}</div>`:'<div class="empty slim">Nenhuma entrega final enviada ainda.</div>'}</section><section class="detail-section"><div class="panel-head"><div><h3>Arquivos do job</h3><div class="panel-sub">Materiais recebidos, referências e versões para aprovação armazenados no Google Drive.</div></div>${preview?'':'<div class="top-actions"><button class="secondary" id="file-upload">Enviar arquivo</button><button class="ghost" id="file-link">Adicionar link</button></div>'}</div>${jobFiles.length?`<div class="file-grid">${jobFiles.map(fileCardHtml).join('')}</div>`:'<div class="empty slim">Nenhum material adicional.</div>'}</section><section class="detail-section"><div class="panel-head"><h3>Comentários</h3></div><div id="comments">${d.comments?.length?d.comments.map(c=>`<div class="comment"><div><b>${esc(c.author_name)}</b><p>${esc(c.body)}</p></div><span>${time(c.created_at)}</span></div>`).join(''):'<span class="muted">Nenhum comentário.</span>'}</div>${preview?'<div class="preview-readonly">Modo de visualização: alterações estão bloqueadas.</div>':'<form id="comment-form" class="comment-form"><input class="input" name="body" placeholder="Escreva uma mensagem" required><button class="primary">Enviar</button></form>'}</section>${admin?`<div class="form-actions split-actions"><button class="danger ghost-danger" id="delete-demand">Excluir task</button><div><button class="ghost" id="copy-demand-link">Copiar link</button><button class="secondary" id="edit-demand">Editar task</button>${d.billing_mode==='one_off'&&Number(d.amount_cents)>0?'<button class="secondary" id="invoice-demand">Ver cobrança</button>':''}</div></div>`:canEdit?`<div class="form-actions"><button class="ghost" id="copy-demand-link">Copiar link da task</button><button class="secondary" id="edit-demand">Editar task</button></div>`:`<div class="form-actions"><button class="ghost" id="copy-demand-link">Copiar link da task</button></div>`}`;
  }
  function fileCardHtml(f){const mime=(f.mime||'').toLowerCase(),kind=mime.startsWith('image/')?'Imagem':mime.startsWith('video/')?'Vídeo':mime.startsWith('audio/')?'Áudio':mime==='application/pdf'?'PDF':mime.startsWith('text/')?'Texto':'Arquivo',canDelete=!S.user.is_preview&&S.user.role!=='client';return `<article class="file-card ${f.kind==='final'?'file-card-final':''}"><div class="file-icon">${kind==='Imagem'?'▧':kind==='Vídeo'?'▶':kind==='Áudio'?'♪':kind==='PDF'?'PDF':'DOC'}</div><div class="file-info"><b>${esc(f.label)}</b><span>${esc(f.original_name||kind)}${f.version_no?` · V${f.version_no}`:''}${f.is_drive?' · Drive':''}</span></div><div class="file-actions">${f.view_url?`<button class="mini-btn preview-file" data-file="${f.id}">Visualizar</button>`:''}${f.download_url?`<a class="mini-btn" href="${esc(f.download_url)}" target="_blank" rel="noopener">Baixar</a>`:''}${f.approval==='approved'?'<span class="status-ok">Aprovado</span>':f.approval==='changes'?'<span class="status-warn">Ajustes</span>':f.kind==='review'&&!S.user.is_preview?`<button class="mini-btn review" data-file="${f.id}">Avaliar</button>`:''}${canDelete?`<button class="mini-btn file-delete-btn delete-file" data-file="${f.id}" title="Excluir anexo">Excluir</button>`:''}</div></article>`}
  function previewFile(d,id){const f=d.files?.find(x=>x.id==id);if(!f)return;if(!f.preview_url){if(f.view_url)window.open(f.view_url,'_blank','noopener');return}const mime=(f.mime||'').toLowerCase();let body='';if(mime.startsWith('image/'))body=`<img class="preview-media" src="${esc(f.preview_url)}" alt="${esc(f.label)}">`;else if(mime.startsWith('video/'))body=`<video class="preview-media" src="${esc(f.preview_url)}" controls autoplay></video>`;else if(mime.startsWith('audio/'))body=`<audio class="preview-audio" src="${esc(f.preview_url)}" controls autoplay></audio>`;else body=`<iframe class="preview-frame" src="${esc(f.preview_url)}" title="${esc(f.label)}"></iframe>`;$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal preview-modal"><div class="modal-head"><div><h3>${esc(f.label)}</h3><div class="help">${esc(f.original_name||'Arquivo')}</div></div><button class="close" data-close>×</button></div>${body}<div class="form-actions"><a class="secondary" href="${esc(f.download_url)}" target="_blank" rel="noopener">Baixar arquivo</a><button class="ghost" data-close>Fechar</button></div></div></div>`;$$('[data-close]').forEach(x=>x.onclick=()=>openDemand(d.id))}
  function wireDetail(d){if($('#comment-form'))$('#comment-form').onsubmit=async e=>{e.preventDefault();try{await api('demands.comment',{demand_id:d.id,body:new FormData(e.target).get('body')},'POST');toast('Comentário enviado');openDemand(d.id)}catch(x){toast(x.message,true)}};$$('.review').forEach(b=>b.onclick=()=>reviewFile(d,b.dataset.file));$$('.preview-file').forEach(b=>b.onclick=()=>previewFile(d,Number(b.dataset.file)));$$('.delete-file').forEach(b=>b.onclick=()=>confirmFileDelete(d,Number(b.dataset.file)));$('#edit-demand')?.addEventListener('click',()=>openDemandForm(d));$('#delete-demand')?.addEventListener('click',()=>confirmDemandDelete(d));$('#invoice-demand')?.addEventListener('click',()=>{closeModal();go('finance',true,true)});$('#copy-demand-link')?.addEventListener('click',async()=>{const url=taskShareUrl(d.id);try{await navigator.clipboard.writeText(url);toast('Link da task copiado')}catch{prompt('Copie o link da task:',url)}});$('#file-link')?.addEventListener('click',()=>addFileLink(d));$('#file-upload')?.addEventListener('click',()=>uploadFileModal(d))}
  function confirmFileDelete(d,id){const f=d.files?.find(x=>Number(x.id)===Number(id));if(!f)return;const driveNote=f.is_drive?' O arquivo também será removido do Google Drive.':' O vínculo será removido desta task.';$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal compact"><div class="modal-head"><div><h3>Excluir anexo?</h3><div class="help">${esc(f.label||f.original_name||'Arquivo')}</div></div><button class="close" id="cancel-file-delete">×</button></div><div class="danger-box">Esta ação não poderá ser desfeita.${driveNote}</div><div class="form-actions"><button class="ghost" id="back-file-delete">Cancelar</button><button class="danger" id="confirm-file-delete">Excluir anexo</button></div></div></div>`;const back=()=>openDemand(d.id);$('#cancel-file-delete').onclick=back;$('#back-file-delete').onclick=back;$('#confirm-file-delete').onclick=async()=>{const btn=$('#confirm-file-delete');btn.disabled=true;btn.textContent='Excluindo…';try{await api('files.delete',{file_id:id},'POST');toast('Anexo excluído');openDemand(d.id)}catch(x){toast(x.message,true);btn.disabled=false;btn.textContent='Excluir anexo'}}}
  function confirmDemandDelete(d){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal compact"><div class="modal-head"><div><h3>Excluir task #${d.id}?</h3><div class="help">${esc(d.title)}</div></div><button class="close" data-close>×</button></div><div class="danger-box">A task será removida do Kanban e das listagens. O histórico permanece preservado no banco para segurança.</div><div class="form-actions"><button class="ghost" data-close>Cancelar</button><button class="danger" id="confirm-demand-delete">Excluir task</button></div></div></div>`;$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#confirm-demand-delete').onclick=async()=>{try{await api('demands.delete',{id:d.id},'POST');toast('Task excluída');closeModal();refresh()}catch(x){toast(x.message,true)}}}
  function openDemandForm(d){closeModal();setTimeout(()=>{openDemand(d.id,true)},0)}
  async function reviewFile(d,id){const choice=(prompt('Digite "aprovar" para aprovar ou "ajustes" para pedir alterações:','aprovar')||'').trim().toLowerCase(),decision={aprovar:'approved',aprovado:'approved',ajustes:'changes',ajuste:'changes'}[choice];if(!decision)return;const message=decision==='changes'?prompt('Descreva os ajustes:',''):'';try{await api('files.review',{file_id:Number(id),decision,message},'POST');toast('Avaliação registrada');openDemand(d.id)}catch(x){toast(x.message,true)}}
