  function uploadFileModal(d){const admin=S.user.role!=='client',drive=clientDriveInfo(d.client_id);if(!drive?.drive_ready){toast('Defina ou reconecte o Google Drive deste cliente antes de enviar arquivos.',true);return}const html=`<div class="modal-backdrop"><div class="modal upload-modal"><div class="modal-head"><div><h3>Enviar para o Google Drive</h3><div class="help">Selecione um ou vários arquivos. Cada item é enviado em blocos e vinculado à mesma task.</div></div><button class="close" data-close>×</button></div><form id="upload-form" class="upload-modal-form"><div class="upload-form-grid"><div class="field"><label>Nome da entrega (opcional)</label><input class="input" name="label" maxlength="255" placeholder="Para vários arquivos, o nome de cada arquivo será usado"></div><div class="field"><label>Arquivos</label><input class="input file-picker-input" name="files" type="file" multiple required></div>${admin?'<div class="field"><label>Tipo</label><select class="select" name="kind"><option value="input">Material recebido</option><option value="reference">Referência</option><option value="review">Versão para aprovação</option><option value="final">Entrega final</option></select></div>':''}</div>${admin?'<label class="check upload-shared"><input type="checkbox" name="shared" value="1" checked> Visível para o cliente</label>':''}<div class="drive-note"><b>Google Drive</b> · envio sequencial em blocos, com progresso por arquivo.<div class="upload-progress hidden" id="upload-progress"><i></i></div><div id="upload-file-status" class="field-help"></div></div><div class="form-actions"><button type="button" class="ghost" data-close>Cancelar</button><button class="primary" id="upload-submit">Enviar ao Drive</button></div></form></div></div>`;$('#modal-root').innerHTML=html;$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#upload-form').onsubmit=async e=>{e.preventDefault();const btn=$('#upload-submit'),fd=new FormData(e.target),files=[...(e.target.elements.files.files||[])];if(!files.length)return;btn.disabled=true;const progress=$('#upload-progress'),status=$('#upload-file-status');progress?.classList.remove('hidden');try{for(let i=0;i<files.length;i++){const file=files[i],custom=String(fd.get('label')||'').trim(),label=files.length===1&&custom?custom:file.name;if(status)status.textContent=`Arquivo ${i+1} de ${files.length}: ${file.name}`;await uploadDemandFile(d.id,file,{label,kind:String(fd.get('kind')||'input'),shared:fd.get('shared')?1:(admin?0:1)},pct=>{btn.textContent=`${i+1}/${files.length} · ${Math.round(pct*100)}%`;const bar=progress?.querySelector('i');if(bar)bar.style.width=`${Math.round(((i+pct)/files.length)*100)}%`})}toast(`${files.length} arquivo(s) salvo(s) no Google Drive`);closeModal();openDemand(d.id)}catch(x){toast(x.message,true);btn.disabled=false;btn.textContent='Tentar novamente'}}}

  async function invoiceDemand(d){const due=prompt('Vencimento (AAAA-MM-DD):',new Date().toISOString().slice(0,10));if(!due)return;try{await api('invoices.from_demand',{demand_id:d.id,due_on:due,installments:1},'POST');toast('Cobrança gerada');openDemand(d.id)}catch(x){toast(x.message,true)}}
