    $('#new-client').onclick=()=>clientModal({},driveAccounts);$$('.edit-client').forEach(b=>b.onclick=()=>clientModal(rows.find(c=>Number(c.id)===Number(b.dataset.id))||{},driveAccounts));$$('.preview-client').forEach(b=>b.onclick=()=>startClientPreview(Number(b.dataset.id)));
    const qp=new URLSearchParams(location.search),connectedId=Number(qp.get('drive_connected')||0);if(connectedId){let draft={};try{draft=JSON.parse(sessionStorage.getItem('taskesc-client-draft')||'{}')||{}}catch{}sessionStorage.removeItem('taskesc-client-draft');history.replaceState({},'',routeUrl('clients'));draft.drive_account_id=connectedId;setTimeout(()=>clientModal(draft,driveAccounts,connectedId),0);toast('Google Drive conectado. Revise o cadastro e salve o cliente.');}
